cards.preview:
SELECT столбцы FROM таблица WHERE условие ORDER BY столбец;
INSERT INTO таблица (a, b) VALUES (1, 2);
UPDATE таблица SET a = 5 WHERE id = 1;
DELETE FROM таблица WHERE id = 1;
JOIN объединяет таблицы по ключу, GROUP BY + COUNT/SUM считает по группам.
Всегда пиши WHERE в UPDATE и DELETE — иначе изменятся все строки.

